def compute_block_hash(block):
    """Deterministic hash computation matching SUT's internal logic."""
    block_string = f"{block['index']}{block['timestamp']}{block['transactions']}{block['previous_hash']}{block['nonce']}"
    return hashlib.sha256(block_string.encode()).hexdigest()


def corrupt_block(block: Dict[str, Any], field: str, value: Any) -> Dict[str, Any]:
    """Return a copy of block with a corrupted field."""
    corrupted = dict(block)
    corrupted[field] = value
    return corrupted


