class TestConcurrency:
    """Validate thread safety and race condition handling."""

    def test_concurrent_submissions(self, consensus_engine):
        """Concurrent block submissions must be atomic."""
        num_threads = 10
        blocks_per_thread = 5

        def submit_blocks(thread_id):
            for i in range(blocks_per_thread):
                block = {
                    "index": thread_id * blocks_per_thread + i + 1,
                    "timestamp": 1722500000 + thread_id * 100 + i,
                    "transactions": [{"tx_id": f"thread_{thread_id}_tx_{i}"}],
                    "previous_hash": "0" * 64,
                    "nonce": thread_id * 1000 + i,
                }
                try:
                    consensus_engine.submit_block(block)
                except (InvalidBlockError, ProposalRejectedError):
                    pass  # Expected for duplicate indices

        threads = []
        for t in range(num_threads):
            thread = threading.Thread(target=submit_blocks, args=(t,))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        # Chain must be consistent
        chain = consensus_engine.get_chain()
        indices = [b["index"] for b in chain]
        assert indices == sorted(indices)
        assert len(indices) == len(set(indices))  # No duplicates

    def test_concurrent_read_write(self, consensus_engine, valid_chain):
        """Concurrent reads during writes must not corrupt state."""
        engine, blocks = valid_chain
        stop_flag = threading.Event()

        def writer():
            i = 100
            while not stop_flag.is_set():
                block = {
                    "index": i,
                    "timestamp": 1722500000 + i,
                    "transactions": [],
                    "previous_hash": "0" * 64,
                    "nonce": i,
                }
                try:
                    engine.submit_block(block)
                except (InvalidBlockError, ProposalRejectedError):
                    pass
                i += 1

        def reader():
            while not stop_flag.is_set():
                chain = engine.get_chain()
                # Validate chain integrity
                for j in range(1, len(chain)):
                    assert chain[j]["previous_hash"] == chain[j-1]["hash"]

        writer_thread = threading.Thread(target=writer)
        reader_threads = [threading.Thread(target=reader) for _ in range(3)]

        writer_thread.start()
        for rt in reader_threads:
            rt.start()

        time.sleep(0.1)  # Let them run
        stop_flag.set()

        writer_thread.join()
        for rt in reader_threads:
            rt.join()

        # Final chain must be valid
        chain = engine.get_chain()
        for j in range(1, len(chain)):
            assert chain[j]["previous_hash"] == chain[j-1]["hash"]

    def test_thread_pool_submission(self, consensus_engine):
        """ThreadPoolExecutor with mixed valid/invalid blocks."""
        def submit_with_validation(block):
            try:
                result = consensus_engine.submit_block(block)
                return ("success", block["index"])
            except (InvalidBlockError, ProposalRejectedError) as e:
                return ("failure", block["index"], str(e))

        tasks = []
        for i in range(1, 21):
            block = {
                "index": i,
                "timestamp": 1722500000 + i,
                "transactions": [],
                "previous_hash": "0" * 64,
                "nonce": i,
            }
            if i % 3 == 0:  # Every 3rd block is corrupted
                block["index"] = 999
            tasks.append(block)

        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = [executor.submit(submit_with_validation, task) for task in tasks]
            results = [f.result() for f in as_completed(futures)]

        successes = [r for r in results if r[0] == "success"]
        failures = [r for r in results if r[0] == "failure"]
        assert len(successes) > 0
        assert len(failures) > 0


