@pytest.mark.skipif(not HYPOTHESIS_AVAILABLE, reason="Hypothesis not installed")
class TestPropertyBased:
    """Property-based validation using Hypothesis."""

    @settings(max_examples=50, suppress_health_check=[HealthCheck.too_slow])
    @given(
        index=st.integers(min_value=1, max_value=1000),
        timestamp=st.integers(min_value=0, max_value=2**32),
        nonce=st.integers(min_value=0, max_value=2**32),
        tx_count=st.integers(min_value=0, max_value=10),
    )
    def test_valid_block_properties(self, consensus_engine, index, timestamp, nonce, tx_count):
        """Valid blocks with random properties must be accepted."""
        transactions = [
            {"tx_id": f"prop_tx_{i}", "data": f"data_{i}"} for i in range(tx_count)
        ]
        block = {
            "index": index,
            "timestamp": timestamp,
            "transactions": transactions,
            "previous_hash": "0" * 64,
            "nonce": nonce,
        }
        try:
            result = consensus_engine.submit_block(block)
            assert result is True
        except (InvalidBlockError, ProposalRejectedError):
            # Duplicate index or other rejection is acceptable
            pass

    @settings(max_examples=50)
    @given(
        index=st.integers(min_value=-100, max_value=0),
        timestamp=st.integers(min_value=-1000, max_value=-1),
    )
    def test_invalid_block_properties(self, consensus_engine, index, timestamp):
        """Invalid blocks must always be rejected."""
        block = {
            "index": index,
            "timestamp": timestamp,
            "transactions": [],
            "previous_hash": "0" * 64,
            "nonce": 0,
        }
        with pytest.raises((InvalidBlockError, ValueError)):
            consensus_engine.submit_block(block)

    @settings(max_examples=30)
    @given(
        hash_length=st.integers(min_value=1, max_value=128),
        hash_char=st.characters(min_codepoint=0x30, max_codepoint=0x39),  # digits only
    )
    def test_hash_length_validation(self, consensus_engine, valid_block, hash_length, hash_char):
        """Hash must be exactly 64 hex characters."""
        bad_hash = hash_char * hash_length
        bad_block = corrupt_block(valid_block, "hash", bad_hash)
        if hash_length != 64:
            with pytest.raises(InvalidBlockError):
                consensus_engine.validate_block(bad_block)
        else:
            # 64-digit hash might be valid if it matches computed hash
            computed = compute_block_hash(valid_block)
            if bad_hash == computed:
                assert consensus_engine.validate_block(valid_block) is True
            else:
                with pytest.raises(InvalidBlockError):
                    consensus_engine.validate_block(bad_block)


