class TestPerformance:
    """Performance characteristics and stress tolerance."""

    def test_sub_second_operation(self, consensus_engine, valid_block):
        """Single block submission must complete in < 100ms."""
        start = time.perf_counter()
        consensus_engine.submit_block(valid_block)
        elapsed = time.perf_counter() - start
        assert elapsed < 0.1, f"Submission took {elapsed:.3f}s"

    def test_bulk_submission_performance(self, consensus_engine):
        """100 block submissions must complete in < 1 second."""
        start = time.perf_counter()
        for i in range(1, 101):
            block = {
                "index": i,
                "timestamp": 1722500000 + i,
                "transactions": [{"tx_id": f"perf_tx_{i}"}],
                "previous_hash": "0" * 64,
                "nonce": i,
            }
            consensus_engine.submit_block(block)
        elapsed = time.perf_counter() - start
        assert elapsed < 1.0, f"Bulk submission took {elapsed:.3f}s"
        assert len(consensus_engine.get_chain()) == 101

    def test_memory_stability(self, consensus_engine):
        """Memory usage must not grow unboundedly."""
        import tracemalloc
        tracemalloc.start()
        baseline = tracemalloc.get_traced_memory()[0]

        for i in range(1, 51):
            block = {
                "index": i,
                "timestamp": 1722500000 + i,
                "transactions": [{"tx_id": f"mem_tx_{i}", "data": "x" * 100}],
                "previous_hash": "0" * 64,
                "nonce": i,
            }
            consensus_engine.submit_block(block)

        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        # Allow 10MB growth for 50 blocks with 100-byte payloads
        assert current - baseline < 10_000_000


