class TestRegressionGuards:
    """Guards against known regression patterns."""

    def test_hash_determinism(self, valid_block):
        """Same block must always produce same hash."""
        hash1 = compute_block_hash(valid_block)
        hash2 = compute_block_hash(valid_block)
        assert hash1 == hash2
        assert len(hash1) == 64
        assert all(c in "0123456789abcdef" for c in hash1)

    def test_genesis_block_immutable(self, consensus_engine):
        """Genesis block must never change."""
        genesis = consensus_engine.get_chain()[0]
        assert genesis["index"] == 0
        assert genesis["previous_hash"] == "0" * 64
        assert genesis["hash"] == compute_block_hash(genesis)

    def test_chain_serialization(self, consensus_engine, valid_chain):
        """Chain must be JSON-serializable."""
        engine, blocks = valid_chain
        chain = engine.get_chain()
        json_str = json.dumps(chain)
        assert json_str is not None
        deserialized = json.loads(json_str)
        assert len(deserialized) == len(chain)

    def test_error_message_clarity(self, consensus_engine, valid_block):
        """Error messages must be descriptive."""
        bad_block = corrupt_block(valid_block, "index", 99)
        with pytest.raises(InvalidBlockError) as exc_info:
            consensus_engine.submit_block(bad_block)
        assert "index" in str(exc_info.value).lower() or "block" in str(exc_info.value).lower()

    def test_state_isolation_between_engines(self):
        """Different engine instances must not share state."""
        engine1 = ConsensusEngine()
        engine2 = ConsensusEngine()
        block = {
            "index": 1,
            "timestamp": 1722500000,
            "transactions": [],
            "previous_hash": "0" * 64,
            "nonce": 0,
        }
        engine1.submit_block(block)
        assert len(engine1.get_chain()) == 2
        assert len(engine2.get_chain()) == 1  # Isolated


